// Regenerates src/data/generated/cyberTargetCountries.js from a local clone of
// github.com/rskyex/cyber-escalation-atlas: every country named as a target in
// at least one cyber case.
//
// Run: npm run gen:cyber-targets [-- <path to cyber-escalation-atlas clone>]
// (default path: ../cyber-escalation-atlas). Commit the generated file.
import { createServer } from 'vite';
import { execFileSync } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';

const atlas = path.resolve(process.argv[2] || '../cyber-escalation-atlas');
const out = path.resolve('src/data/generated/cyberTargetCountries.js');

// Cyber Atlas names that differ from the Nuclear Atlas country names
const ALIASES = {
  USA: 'United States', US: 'United States', 'United States of America': 'United States',
  UK: 'United Kingdom', 'Great Britain': 'United Kingdom',
  'Republic of Korea': 'South Korea', Korea: 'South Korea',
  UAE: 'United Arab Emirates', Czechia: 'Czech Republic', Türkiye: 'Turkey',
};

const git = (...args) => execFileSync('git', ['-C', atlas, ...args], { encoding: 'utf8' }).trim();
const commit = git('rev-parse', 'HEAD');
const dirty = git('status', '--porcelain', '--untracked-files=no');
if (dirty) {
  console.error(`${atlas} has uncommitted changes; check out a clean commit first.`);
  process.exit(1);
}

const server = await createServer({
  root: atlas,
  configFile: false,
  appType: 'custom',
  logLevel: 'error',
  resolve: { alias: { '@': path.join(atlas, 'src') } },
  server: { middlewareMode: true, hmr: false, ws: false },
});
let incidents;
try {
  ({ seedIncidents: incidents } = await server.ssrLoadModule('/src/data/incidents/index.ts'));
} finally {
  await server.close();
}

const cases = {};
for (const inc of incidents) {
  for (const raw of inc.infrastructure?.targetCountries ?? []) {
    const name = ALIASES[raw] ?? raw;
    (cases[name] ??= []).push(inc.slug);
  }
}
const countries = Object.keys(cases).sort();

const body = `// Generated by scripts/gen-cyber-targets.mjs — do not edit by hand.
// Every target named in at least one Cyber Escalation Atlas case. Labels that are
// not countries ("Global", regions, alliances) never match a plant's host country.
export const cyberAtlasSource = {
  repo: 'https://github.com/rskyex/cyber-escalation-atlas',
  commit: '${commit}',
  cases: ${incidents.length},
};

export const cyberTargetCountries = {
${countries.map((c) => `  ${JSON.stringify(c)}: ${JSON.stringify(cases[c])},`).join('\n')}
};
`;
mkdirSync(path.dirname(out), { recursive: true });
writeFileSync(out, body);
console.log(`Wrote ${countries.length} target names from ${incidents.length} cases at ${commit.slice(0, 7)}`);
console.log(countries.join(' | '));
